import { getAllProducts } from "@/lib/db";
import { revalidateTag } from "next/cache";
import { cacheTag } from "next/cache";

interface Product {
  id: number;
  name: string;
  price: number;
}

async function getCachedProducts() {
  "use cache";
  cacheTag("products");
  return getAllProducts();
}

export async function ProductList() {
  const products = (await getCachedProducts()) as Product[];

  async function invalidateProducts() {
    "use server";
    revalidateTag("products");
  }

  return (
    <div className="p-6 border rounded-xl shadow-sm bg-white max-w-md">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-xl font-bold text-gray-800">Products</h2>
        <span className="text-xs px-2 py-1 bg-green-100 text-green-700 rounded-full font-medium">
          Cached
        </span>
      </div>

      <ul className="space-y-3 mb-6">
        {products.map((product) => (
          <li key={product.id} className="flex justify-between items-center p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
            <span className="text-gray-700">{product.name}</span>
            <span className="font-semibold text-gray-900">${product.price}</span>
          </li>
        ))}
      </ul>

      <form action={invalidateProducts}>
        <button 
          type="submit"
          className="w-full py-2.5 px-4 bg-black text-white rounded-lg hover:bg-gray-800 focus:ring-2 focus:ring-offset-2 focus:ring-black transition-all text-sm font-medium"
        >
          Revalidate "products" Tag
        </button>
        <p className="mt-3 text-xs text-gray-500 text-center">
          Submitting this form invalidates the cache tag.
        </p>
      </form>
    </div>
  );
}

